function find(id){return filters.find(f=>f.id===id);}
function properties(D,id,qb){const f=find(id);if(!f||f.category==='special')throw Error('This device is outside the urea hollow-fibre dialyzer model.');const p={...D.defaults};for(const [k,v]of Object.entries(f.properties))if(k in p)p[k]=v;if(qb!==undefined)p.feedFlow_mLmin=qb;return D.validate(p);}
function assumptions(f){return ['length_mm','diameter_um','thickness_um','Lp','porosity','tortuosity','packing','membraneDiffusivity','hindrance'].filter(k=>!(k in f.properties));}
function comparable(f){return f.category!=='special'?f.benchmarks.filter(b=>b.qf===undefined||b.qf===0):[];}
const api={filters,find,properties,assumptions,comparable};if(typeof module!=='undefined'&&module.exports)module.exports=api;root.DialyzerCatalog=api;
